WITH agg AS ( SELECT cp.cp_department, cp.cp_type, cp.cp_catalog_number, SUM(i.inv_quantity_on_hand) AS total_quantity, COUNT(DISTINCT i.inv_item_sk) AS distinct_items, AVG(i.inv_quantity_on_hand) AS avg_quantity, COUNT(DISTINCT r.r_reason_id) AS distinct_reasons FROM catalog_page cp JOIN inventory i ON i.inv_date_sk = cp.cp_start_date_sk LEFT JOIN reason r ON r.r_reason_sk = (i.inv_quantity_on_hand % 5) + 1 WHERE cp.cp_type = 'monthly' AND cp.cp_catalog_number BETWEEN 2 AND 4 AND i.inv_quantity_on_hand > 0 GROUP BY cp.cp_department, cp.cp_type, cp.cp_catalog_number HAVING SUM(i.inv_quantity_on_hand) > 1000 ) SELECT agg.cp_department, agg.cp_type, agg.cp_catalog_number, agg.total_quantity, agg.distinct_items, agg.avg_quantity, agg.distinct_reasons, ROW_NUMBER() OVER (PARTITION BY agg.cp_type ORDER BY agg.total_quantity DESC) AS dept_rank FROM agg ORDER BY agg.total_quantity DESC LIMIT 50
